@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_fb332b188a2b40caae0120af5c2befb0.Models
@using sv_fb332b188a2b40caae0120af5c2befb0.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <h3>Recipes — Cuisine @CuisineId</h3>
    @if (_displayedRecipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <ul>
            @foreach (var recipe in _displayedRecipes)
            {
                <li>
                    <strong>@recipe.Title</strong> (@recipe.PrepTimeMinutes min)
                    <br />@recipe.Description
                </li>
            }
        </ul>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private List<Recipe> _displayedRecipes = new();
    private bool _isRefreshing;
    private string? _error;

    private CancellationTokenSource? _loadCts;
    private int _lastLoadedCuisineId;

    protected override Task OnParametersSetAsync()
    {
        // Only reload data when the cuisine changes, not when sort changes
        if (CuisineId != _lastLoadedCuisineId)
        {
            return LoadRecipesAsync();
        }

        // Sort changed — just reorder existing data
        ApplySort();
        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }
        _loadCts = new CancellationTokenSource();
        var ct = _loadCts.Token;

        _lastLoadedCuisineId = CuisineId;
        _error = null;

        // Determine loading state based on whether we already have data
        if (_recipes is null)
        {
            _isRefreshing = false; // will show the full loading placeholder
        }
        else
        {
            _isRefreshing = true; // keep existing data visible
        }

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, ct);

            _recipes = results;
            _isRefreshing = false;
            ApplySort();
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Load was intentionally cancelled (user navigated to different cuisine or left page)
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private void ApplySort()
    {
        if (_recipes is null)
        {
            _displayedRecipes = new();
            return;
        }

        _displayedRecipes = Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes.ToList(),
        };
    }

    private Task RetryAsync()
    {
        _lastLoadedCuisineId = 0; // force reload
        return LoadRecipesAsync();
    }

    public void Dispose()
    {
        if (_loadCts is not null)
        {
            _loadCts.Cancel();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }
}

